	\begin{axis}[
	tick label style={font=\footnotesize},
	label style={font=\small},
	tick style={draw=none},
	axis line style = {-stealth, thick},
	axis equal,
	axis x line*=middle,
	axis y line*=middle,
	view={0}{90},
	xmin = -0.25, xmax=1.25, 
	ymin = -0.6, ymax=1.25,  
	xtick = {-10,10},
	ytick = {-10,10},
	%% Here, we can control the positioning of each individual tick.
	y tick label style={yshift={(\tick==2)*5pt}},
	y tick label style={yshift={(\tick==-2)*-5pt}},
	x tick label style={xshift={(\tick==2)*5pt}},
	x tick label style={xshift={(\tick==-2)*-7pt}}, 
	ticklabel style={outer sep=3pt} ,   
