%\draw[-latex, very thick, fadedpink] (axis cs: {0.25},{0.5}) -- (axis cs: {0.96},{1.21}) node[right, black] {$\mathbf{T}$};

% Curve C1
\plot[domain = {0}:{1},samples = 100,color = deepskyblue,line width = 1.2pt,
decoration={markings,mark=between positions 0.2 and 1 step 0.3 with {\arrow[]{>};}},
postaction={decorate}
]({\x^2},{\x});

%Rotation
%\draw[->, thick] plot[domain=45:{43-88}] (axis cs:{0.2*cos(\x)+0.25},{0.2*sin(\x)+0.5}) node[right = 17 pt, above = 6 pt] {$90^\circ$};

\node[circle, draw=none, fill=deepskyblue, inner sep=1.5pt] at (axis cs:0,0) {};
\node[circle, draw=none, fill=deepskyblue, inner sep=1.5pt] at (axis cs:1,1) {};	

\draw[-latex, very thick, orangepeel] (axis cs: {0.49},{0.7}) -- (axis cs: {0.847},{0.2}) node[right, black] {$\mathbf{n}$};

\end{axis}

	\end{tikzpicture}

